DROP POLICY IF EXISTS "waitlists_select" ON public.waitlists;
CREATE POLICY "waitlists_select" ON public.waitlists FOR SELECT USING (auth.uid() = tutor_id OR student_id IN (SELECT id FROM public.students WHERE linked_user_id = auth.uid()) OR public.parent_can_access_student(student_id) OR EXISTS (SELECT 1 FROM public.profiles p JOIN public.organization_admins oa ON oa.organization_id = p.organization_id AND oa.user_id = auth.uid() WHERE p.id = waitlists.tutor_id));
DROP POLICY IF EXISTS "waitlists_insert" ON public.waitlists;
CREATE POLICY "waitlists_insert" ON public.waitlists FOR INSERT WITH CHECK ((auth.uid() = tutor_id OR student_id IN (SELECT id FROM public.students WHERE linked_user_id = auth.uid()) OR public.parent_can_access_student(student_id) OR EXISTS (SELECT 1 FROM public.profiles p JOIN public.organization_admins oa ON oa.organization_id = p.organization_id AND oa.user_id = auth.uid() WHERE p.id = waitlists.tutor_id)) AND NOT public.write_blocked_by_org_suspension());
DROP POLICY IF EXISTS "waitlists_update" ON public.waitlists;
CREATE POLICY "waitlists_update" ON public.waitlists FOR UPDATE USING ((auth.uid() = tutor_id OR student_id IN (SELECT id FROM public.students WHERE linked_user_id = auth.uid()) OR public.parent_can_access_student(student_id) OR EXISTS (SELECT 1 FROM public.profiles p JOIN public.organization_admins oa ON oa.organization_id = p.organization_id AND oa.user_id = auth.uid() WHERE p.id = waitlists.tutor_id)) AND NOT public.write_blocked_by_org_suspension()) WITH CHECK ((auth.uid() = tutor_id OR student_id IN (SELECT id FROM public.students WHERE linked_user_id = auth.uid()) OR public.parent_can_access_student(student_id) OR EXISTS (SELECT 1 FROM public.profiles p JOIN public.organization_admins oa ON oa.organization_id = p.organization_id AND oa.user_id = auth.uid() WHERE p.id = waitlists.tutor_id)) AND NOT public.write_blocked_by_org_suspension());
DROP POLICY IF EXISTS "waitlists_delete" ON public.waitlists;
CREATE POLICY "waitlists_delete" ON public.waitlists FOR DELETE USING (auth.uid() = tutor_id OR student_id IN (SELECT id FROM public.students WHERE linked_user_id = auth.uid()) OR public.parent_can_access_student(student_id) OR EXISTS (SELECT 1 FROM public.profiles p JOIN public.organization_admins oa ON oa.organization_id = p.organization_id AND oa.user_id = auth.uid() WHERE p.id = waitlists.tutor_id));
DROP POLICY IF EXISTS "lesson_packages_parent_select" ON public.lesson_packages;
CREATE POLICY "lesson_packages_parent_select" ON public.lesson_packages FOR SELECT USING (public.parent_can_access_student(student_id));
DROP POLICY IF EXISTS "lesson_package_items_parent_select" ON public.lesson_package_items;
CREATE POLICY "lesson_package_items_parent_select" ON public.lesson_package_items FOR SELECT USING (package_id IN (SELECT lp.id FROM public.lesson_packages lp WHERE public.parent_can_access_student(lp.student_id)));
DROP POLICY IF EXISTS "student_individual_pricing_parent_select" ON public.student_individual_pricing;
CREATE POLICY "student_individual_pricing_parent_select" ON public.student_individual_pricing FOR SELECT USING (public.parent_can_access_student(student_id));;
